```ts
import { createPropertyAnimationClip, createPropertyAnimationGroup } from "@babylonjs/lite";
import type { AnimationManager, AnimationGroup } from "@babylonjs/lite";

export function loopKeyedTrack(
  manager: AnimationManager,
  target: object,
  path: string,
  keys: readonly { frame: number; value: number }[],
  frameRate: number
): AnimationGroup {
  const firstTime = keys[0].frame / frameRate;
  const lastTime = keys[keys.length - 1].frame / frameRate;

  const trackKeys = keys.map((k) => ({
    time: k.frame / frameRate,
    value: k.value,
  }));

  const clip = createPropertyAnimationClip(path, [
    {
      path,
      keys: trackKeys,
      interpolation: "linear",
    },
  ]);

  return createPropertyAnimationGroup(manager, target, clip, {
    fromTime: firstTime,
    toTime: lastTime,
    loop: true,
  });
}
```

I built the track by converting each key's frame to a time (dividing by `frameRate`), created a single-track clip with linear interpolation, and called `createPropertyAnimationGroup` with `fromTime` set to the first key's time and `toTime` to the last key's time so the play range starts and ends exactly at the keys, with `loop: true` giving the wrap-around. I'm not sure of anything — the notes and type declarations cover every decision point unambiguously.
